package com.vandorlabs.client;
import com.google.gson.*;
import com.vandorlabs.programmer.*;
import com.vandorlabs.items.ModItems;
import java.nio.file.*;
import java.util.*;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.item.*;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.*;
import net.minecraft.util.math.BlockPos;
import net.minecraftforge.items.wrapper.InvWrapper;
/** Actual three-slot inventory/wrapper and socket ownership calls, including Creative consumption. */
public final class ProgrammerInventoryLegacyChecks {
 private static ProgrammerBlock BLOCK;
 private static final BlockPos POS=new BlockPos(0,80,0);
 private static ItemStack sample(int choice,int count){if(choice==0)return ItemStack.EMPTY;ItemStack result=new ItemStack(choice==1?net.minecraft.init.Items.STICK:choice<5?ModItems.ACCESS_CARD:ModItems.DATA_CHIP,count,choice==2||choice==5?0:choice==4||choice==9?7:2);if(choice>=6){NBTTagCompound tag=new NBTTagCompound();tag.setString("ChipType",choice==6?"master":choice==7?"journal":choice==8?"vehicle":"master");if(choice==7){tag.setString("JournalTitle","Committed Journal");net.minecraft.nbt.NBTTagList pages=new net.minecraft.nbt.NBTTagList();pages.appendTag(new net.minecraft.nbt.NBTTagString("Saved page"));tag.setTag("JournalPages",pages);}tag.setString("OpaqueItem","retained");result.setTagCompound(tag);}return result;}
 private static JsonObject stack(ItemStack value){JsonObject row=new JsonObject();row.addProperty("kind",value.isEmpty()?0:value.getItem()==ModItems.ACCESS_CARD?1:value.getItem()==ModItems.DATA_CHIP?2:3);row.addProperty("count",value.getCount());row.addProperty("company",value.isEmpty()?0:value.getMetadata());row.addProperty("tag",value.hasTagCompound()?value.getTagCompound().toString():"");return row;}
 private static JsonArray slots(ProgrammerTile tile){JsonArray result=new JsonArray();for(int slot=0;slot<3;slot++)result.add(stack(tile.getStackInSlot(slot)));return result;}
 private static ProgrammerTile installed(NonRenderingChecks.MemoryWorld world){world.setBlockState(POS,BLOCK.getDefaultState(),2);return (ProgrammerTile)world.getTileEntity(POS);}
 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();BLOCK=new ProgrammerBlock();net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(ProgrammerTile.class,new ResourceLocation("vandorlabs:data_chip_programmer"));net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(ModItems.ACCESS_CARD);net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(ModItems.DATA_CHIP);JsonArray cases=new JsonArray(),sockets=new JsonArray(),timers=new JsonArray();
  String[] operations={"set","decr0","decr1","decr64","remove","clear","insertSim","insert","extractSim","extract"};for(int slot=0;slot<3;slot++)for(int initial:new int[]{0,3,7})for(int choice=0;choice<10;choice++)for(int count:new int[]{1,2})for(String op:operations){NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);ProgrammerTile tile=installed(world);tile.setInventorySlotContents(slot,sample(initial,1));world.updates=0;ItemStack argument=sample(choice,count),result=ItemStack.EMPTY;InvWrapper wrapper=new InvWrapper(tile);switch(op){case "set":tile.setInventorySlotContents(slot,argument);break;case "decr0":result=tile.decrStackSize(slot,0);break;case "decr1":result=tile.decrStackSize(slot,1);break;case "decr64":result=tile.decrStackSize(slot,64);break;case "remove":result=tile.removeStackFromSlot(slot);break;case "clear":tile.clear();break;case "insertSim":result=wrapper.insertItem(slot,argument,true);break;case "insert":result=wrapper.insertItem(slot,argument,false);break;case "extractSim":result=wrapper.extractItem(slot,count,true);break;case "extract":result=wrapper.extractItem(slot,count,false);break;default:throw new AssertionError(op);}JsonObject row=new JsonObject();row.addProperty("slot",slot);row.addProperty("initial",initial);row.addProperty("choice",choice);row.addProperty("count",count);row.addProperty("op",op);row.add("argument",stack(argument));row.add("result",stack(result));row.add("slots",slots(tile));row.addProperty("argumentAlias",!argument.isEmpty()&&tile.getStackInSlot(slot)==argument);row.addProperty("journal",tile.journal);row.addProperty("title",tile.title);row.addProperty("updates",world.updates);cases.add(row);}
  for(int slot=0;slot<3;slot++)for(int initial:new int[]{0,3,6,7})for(int choice=0;choice<10;choice++)for(boolean creative:new boolean[]{false,true})for(int permission=0;permission<7;permission++){final int auth=permission;final boolean[] unavailable={false};NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false){@Override public boolean isBlockLoaded(BlockPos pos){return !(auth==6&&unavailable[0]&&pos.equals(POS))&&super.isBlockLoaded(pos);}};ProgrammerTile tile=installed(world);tile.setInventorySlotContents(slot,sample(initial,1));EntityPlayer actor=new EntityPlayer(world,new com.mojang.authlib.GameProfile(new UUID(0,41),"ProgrammerSocket")){public boolean isSpectator(){return auth==2;}public boolean isCreative(){return capabilities.isCreativeMode;}public boolean canPlayerEdit(BlockPos pos,EnumFacing face,ItemStack held){return auth!=4;}};actor.capabilities.isCreativeMode=creative;actor.isDead=permission==1;actor.setPosition(permission==3?20:.5,80,-1.5);if(permission==5)world.tiles.put(POS,new ProgrammerTile());actor.setHeldItem(EnumHand.MAIN_HAND,sample(choice,2));world.updates=0;unavailable[0]=true;boolean accepted=tile.interactSocket(actor,EnumHand.MAIN_HAND,slot);JsonObject row=new JsonObject();row.addProperty("slot",slot);row.addProperty("initial",initial);row.addProperty("choice",choice);row.addProperty("creative",creative);row.addProperty("permission",permission);row.addProperty("accepted",accepted);row.add("held",stack(actor.getHeldItemMainhand()));row.add("slots",slots(tile));row.addProperty("journal",tile.journal);row.addProperty("vehicle",tile.vehicle);row.addProperty("updates",world.updates);sockets.add(row);}
  NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);ProgrammerTile tile=installed(world);tile.setInventorySlotContents(1,sample(7,1));if(!tile.program())throw new AssertionError("Timer setup");for(int tick=0;tick<=85;tick++){JsonObject row=new JsonObject();NBTTagCompound saved=tile.writeToNBT(new NBTTagCompound());row.addProperty("tick",tick);row.addProperty("writing",saved.getInteger("Writing"));row.addProperty("complete",saved.getInteger("Complete"));row.addProperty("status",tile.getProgrammerStatus().name());timers.add(row);tile.update();}
  JsonObject root=new JsonObject();root.addProperty("schema",1);root.add("cases",cases);root.add("sockets",sockets);root.add("timers",timers);StringBuilder golden=new StringBuilder();for(byte value:java.security.MessageDigest.getInstance("SHA-256").digest(root.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)))golden.append(String.format(Locale.ROOT,"%02x",value&255));if(cases.size()!=1800||sockets.size()!=1680||timers.size()!=86||!golden.toString().equals("488ea87cd420cc0f0520ed3e1f21d54d44ac393d240743099698485ae8b3f678"))throw new AssertionError("Released programmer inventory changed: "+golden);root.addProperty("golden",golden.toString());Path output=Paths.get(System.getProperty("vandorlabs.programmerInventoryReference","build/test-artifacts/programmer-inventory-forge.json"));Files.createDirectories(output.toAbsolutePath().getParent());try(java.io.Writer writer=Files.newBufferedWriter(output)){new Gson().toJson(root,writer);}System.out.println("Actual programmer inventory Source PASS cases="+cases.size()+" sockets="+sockets.size()+" timers="+timers.size()+" golden="+golden);
 }
}
